    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        check("initials(\"Ada King Lovelace\")", "A.K.L.", InitialsMaker.initials("Ada King Lovelace"));
        check("initials(\"grace hopper\")", "G.H.", InitialsMaker.initials("grace hopper"));
        check("initials(\"plato\")", "P.", InitialsMaker.initials("plato"));
        check("initials(\"  alan   turing  \")", "A.T.", InitialsMaker.initials("  alan   turing  "));
        check("initials(\"\")", "", InitialsMaker.initials(""));
        check("initials(\"   \")", "", InitialsMaker.initials("   "));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

